import { ErrorBoundary, Suspense } from '@suspensive/react';
import { QueryErrorResetBoundary } from '@tanstack/react-query';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { FullScreenLoading } from '~/widgets/loading/full-screen-loading';
import { useSetHeaderTitle, useSetIsPullToRefreshEnabled } from '~/widgets/sub-layout/use-sub-layout';
import { NoticeContent } from '~/entities/community/ui/notice-content';
import i18n from '~/shared/i18n/i18n';

export const NoticePage = () => {
  useSetIsPullToRefreshEnabled(true);
  useSetHeaderTitle(i18n.t('notice'));

  return (
    <div className="content sub">
      <div className="board-list">
        <QueryErrorResetBoundary>
          {({ reset }) => (
            <ErrorBoundary fallback={FallbackErrorMessage} onReset={reset}>
              <Suspense fallback={<FullScreenLoading />}>
                <NoticeContent />
              </Suspense>
            </ErrorBoundary>
          )}
        </QueryErrorResetBoundary>
      </div>
    </div>
  );
};
