import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { EmptyList } from '~/widgets/empty-list';
import {
  resetNoticeListQuery,
  useNoticeListInfiniteQuery,
} from '~/entities/community/api/use-notice-list-infinite-query';
import { CommunityParams } from '~/entities/community/model/types';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks/use-navigate';
import { parseToDate } from '~/shared/lib/web-view-bridge';
import { PATHS } from '~/shared/routes/paths';

export const NoticeContent = () => {
  const { navigate } = useNavigate();
  const { data: list, fetchNextPage, hasNextPage, markAsRead } = useNoticeListInfiniteQuery({});

  const [ref, inView] = useInView();

  const fnGoDetail = async (item: CommunityParams) => {
    if (item.nttManageId) {
      markAsRead(item.nttManageId);
    }
    navigate(`${PATHS.community.noticeDetail}${item.nttManageId}`, { state: item.nttManageId });
  };

  useEffect(() => {
    if (hasNextPage && inView) fetchNextPage();
  }, [hasNextPage, inView, fetchNextPage]);

  const flattenList = list?.pages.map((page) => page?.result?.list).flat() || [];

  if (!list || flattenList.length === 0) {
    return <EmptyList message={i18n.t('validation:noNoticesAvailable')} reset={resetNoticeListQuery} />;
  }

  return (
    <ul>
      {flattenList?.map(
        (item, index) =>
          item && (
            <li key={`li_${item.nttManageId}_${index}`} ref={index + 1 === flattenList.length ? ref : null}>
              <button
                type="button"
                onClick={() => {
                  fnGoDetail(item);
                }}
              >
                <p>
                  {item.nttSj}
                  {!item.isRead && <span className="new">{i18n.t('newPost')}</span>}
                </p>
                <span>{parseToDate(item.registDt, 'yyyy.MM.dd')}</span>
              </button>
            </li>
          ),
      )}
    </ul>
  );
};
